"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3252],{46743:e=>{e.exports=JSON.parse('{"functions":[{"name":"getProductInfo","desc":"Fetches info for a marketplace asset, gamepass or developer product.\\n\\nYields, and retries up to 4 times spaced 3 seconds apart. Returns `nil` once the\\nattempts are exhausted. Only `PriceInRobux` is surfaced in the return type, since\\nthat is all callers here need.\\n\\n```lua\\nlocal info = getProductInfo(gamepassId, Enum.InfoType.GamePass)\\nlocal price = info and info.PriceInRobux\\n```","params":[{"name":"productId","desc":"Asset, gamepass or product id","lua_type":"Types.RblxId"},{"name":"infoType","desc":"Which marketplace catalog to query","lua_type":"Enum.InfoType"}],"returns":[{"desc":"Product info, or nil if every attempt failed","lua_type":"{ PriceInRobux: number }?"}],"function_type":"static","source":{"line":38,"path":"src/Shared/Modules/getProductInfo.luau"}}],"properties":[],"types":[],"name":"getProductInfo","desc":"Retry wrapper around `MarketplaceService:GetProductInfo()`.\\n\\nProduct info requests are rate limited and fail intermittently, so the call is\\nretried a few times with a delay before giving up.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":12,"path":"src/Shared/Modules/getProductInfo.luau"}}')}}]);